```javascript
const { Client, GatewayIntentBits, REST, Routes, SlashCommandBuilder } = require('discord.js');

// Luodaan uusi Discord client
const client = new Client({
    intents: [
        GatewayIntentBits.Guilds,
    ]
});

// Botin token (korvaa 'YOUR_BOT_TOKEN' oikealla tokenillasi)
const token = 'YOUR_BOT_TOKEN';

// Luodaan slash-komento
const commands = [
    new SlashCommandBuilder()
        .setName('ban')
        .setDescription('Ban a user from the server')
        .addUserOption(option =>
            option.setName('target')
                .setDescription('The user to ban')
                .setRequired(true))
        .addStringOption(option =>
            option.setName('reason')
                .setDescription('The reason for the ban')
                .setRequired(false)),
];

const rest = new REST({ version: '10' }).setToken(token);

client.once('ready', async () => {
    console.log(`Logged in as ${client.user.tag}!`);

    try {
        console.log('Started refreshing application (/) commands.');

        await rest.put(
            Routes.applicationGuildCommands(client.user.id, 'YOUR_GUILD_ID'),
            { body: commands },
        );

        console.log('Successfully reloaded application (/) commands.');
    } catch (error) {
        console.error(error);
    }
});

// Käsitellään slash-komento
client.on('interactionCreate', async interaction => {
    if (!interaction.isChatInputCommand()) return;

    if (interaction.commandName === 'ban') {
        const user = interaction.options.getUser('target');
        const reason = interaction.options.getString('reason') || 'No reason provided';

        if (!interaction.guild.members.me.permissions.has("BanMembers")) {
            return interaction.reply({ content: "I do not have permission to ban members!", ephemeral: true });
        }

        const member = interaction.guild.members.cache.get(user.id);

        if (!member) {
            return interaction.reply({ content: "User not found in this guild.", ephemeral: true });
        }

        member.ban({ reason })
            .then(() => interaction.reply({ content: `Successfully banned ${user.tag}. Reason: ${reason}` }))
            .catch(error => {
                console.error(error);
                interaction.reply({ content: `Failed to ban ${user.tag}`, ephemeral: true });
            });
    }
});

// Kirjaudu sisään botilla käyttäen tokenia
client.login(token);
```

### Huomioitavaa

- Korvaa `'YOUR_BOT_TOKEN'` ja `'YOUR_GUILD_ID'` oikeilla tiedoilla.
- Tarkista, että sinulla on oikeat käyttöoikeudet bannata käyttäjiä palvelimella.
- Muista käsitellä virheitä ja varmistaa, että bottisi toimii myös poikkeustilanteissa.

