```cpp
#include <cmark.h>
#include <string>

std::string markdownToHtml(const std::string& markdown) {
    // Luo uusi Markdown-parseri
    cmark_parser *parser = cmark_parser_new(CMARK_PARSER_OPTIONS_DEFAULT);

    // Parsii Markdown-merkinnän
    cmark_node *doc = cmark_parser_parse(parser, markdown.c_str());

